const d = n => new Date(Date.now() - n*86400000).toISOString().slice(0,10);
const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
return [
 {id:'R-01', source:'google', author:'Helen P.', rating:5, text:'Best carbonara in town and lovely staff.', posted:d(0), replied:false},
 {id:'R-02', source:'google', author:'Jon S.', rating:2, text:'Waited 50 minutes for mains and nobody apologised.', posted:d(0), replied:false},
 {id:'R-03', source:'tripadvisor', author:'Mia K.', rating:4, text:'Great food, a bit loud on Friday night.', posted:d(1), replied:false},
 {id:'R-04', source:'google', author:'Omar D.', rating:5, text:'Perfect anniversary dinner.', posted:d(6), replied:true}
].map(json => ({json}));

return $input.all().map(({json}) => {
 const sentiment = json.rating >= 4 ? 'positive' : json.rating === 3 ? 'mixed' : 'negative';
 return {json: {...json, sentiment, owner_alert: json.rating <= 3, needs_action: !json.replied, reason: json.replied ? 'already answered' : `${sentiment} review without a reply`}};
});

return $input.all().map(({json}) => {
 const first = json.author.split(' ')[0];
 const message = json.sentiment === 'negative'
  ? `Dear ${first}, thank you for telling us. A wait like that is not the evening we want anyone to have, and I am sorry. Please write to hello@example.com so I can put it right personally.`
  : json.sentiment === 'mixed'
  ? `Dear ${first}, thank you for the honest feedback. We are looking at what you mentioned and hope to welcome you again.`
  : `Dear ${first}, thank you for the kind words. We are glad you enjoyed your visit and look forward to seeing you again.`;
 return {json: {...json, channel: json.source, subject:`Reply to ${json.rating}-star review`, message, approval:'owner_approves'}};
});
